window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["02"]={"https://www.gov.uk/foreign-travel-advice/azerbaijan":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"c2a4809c0984d708d5fa34409f695dff62e69005323e584f682afaf4e15cec0b","read":"https://www.gov.uk/api/content/foreign-travel-advice/azerbaijan","bytes":81907,"x":"fulltext v1","title":"Azerbaijan travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-27T00:00:00+00:00","mod":"2026-10-23T13:44:51+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Azerbaijan-Armenia border"]},{"k":"p","s":["The border with Armenia remains closed. The FCDO advises against all travel to within 5km of the border with Armenia, due to tensions between Azerbaijan and Armenia. Note that this does not include the border of Azerbaijan’s Nakhchivan exclave with Armenia."]},{"k":"h","s":["Areas where FCDO advises against all but essential travel"]},{"k":"hs","s":["South-western Azerbaijan (those regions affected by conflict in 2020 and 2023)"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) advises against all but essential travel to:"]},{"k":"li","s":["The districts (‘rayons’) of Kelbajar, Lachin, Qubadli, Zengilan, Jabrayil, Fuzuli, Khojavand, Shusha, Khojali, Khankendi, Aghdam and Tartar"]},{"k":"p","s":["You should follow Azerbaijani national government and local authorities’ advice in areas that have not been cleared of mines or unexploded ordnance."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/azerbaijan/regional-risks"],"."]},{"k":"h","s":["UK government support"]},{"k":"p","s":["Help for British nationals is extremely limited in the areas where we advise against travel."]},{"k":"h","s":["Regional escalation"]},{"k":"p","s":["There is a heightened risk of regional tension. Escalation could lead to travel disruption, including airspace closures and other unanticipated impacts."]},{"k":"p","s":["British nationals should take sensible precautions, considering their own individual circumstances. These include:"]},{"k":"li","s":["read ",["if you’re affected by a crisis abroad - GOV.UK","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],". This includes guidance on “how to prepare for a crisis” with suggestions on what you might include in your emergency supplies and “what to do in a crisis”"]},{"k":"li","s":["sign up to FCDO Travel Advice email alerts"]},{"k":"li","s":["monitor local and international media for the latest information"]},{"k":"li","s":["follow the instructions of the local authorities"]},{"k":"p","s":["For information on crossing the border from Iran into Azerbaijan, see ",["Entry requirements","https://www.gov.uk/foreign-travel-advice/azerbaijan/entry-requirements"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/azerbaijan/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/travelaware/"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Azerbaijan’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Azerbaijan set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Azerbaijani Embassy in the UK.","https://london.mfa.gov.az/en"]]},{"k":"h","s":["Entering Azerbaijan across the land border from Iran"]},{"k":"p","s":["The border between Azerbaijan and Iran is closed. But British nationals might be able to cross at the Astara border crossing with special authorisation from the Government of Azerbaijan, which must be facilitated by the British Embassy in Baku. British nationals seeking entry into Azerbaijan should ",["contact the FCDO","https://www.contact.service.csd.fcdo.gov.uk/home"]," before travelling to the border crossing at Astara, indicating whether you are contacting from Iran or from the UK on behalf of a relative. Other border crossings to Azerbaijan remain closed."]},{"k":"p","s":["British nationals will need to provide personal details (name, date of birth, passport information). The British Embassy will provide confirmation and a code from the Azerbaijani authorities. This can take several weeks. You should not travel to the border until you have received confirmation. You will need to show the code before crossing. You will also need to apply for a visa through the normal process. See ‘applying for a visa’."]},{"k":"p","s":["If you intend to leave Iran overland, you do so at your own risk. In Iran, holding a British passport or having perceived connections to the UK can be reason enough for the Iranian authorities to detain you."]},{"k":"p","s":["Read more FCDO advice ",["if you’re affected by a crisis abroad","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Azerbaijan as a visitor, your passport must usually have an ‘expiry date’ at least 6 months after the date you arrive and at least 2 blank pages for entry stamps. See ‘visa requirements’ for more details."]},{"k":"p","s":["To enter Azerbaijan as a resident, your passport must have an ‘expiry date’ at least 3 months after the expiry date of your temporary or permanent residence permit."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"p","s":["If you need to travel on a UK Emergency Travel Document, check the visa requirements below before making your travel arrangements."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"hs","s":["British-Azerbaijani dual nationals"]},{"k":"p","s":["Azerbaijan does not recognise dual nationality, but does not prohibit Azerbaijani nationals from holding dual nationality. You must inform the local Azerbaijani Embassy or State Migration Service within one month of taking up another nationality. If you do not, this can impact the level of consular support FCDO will be able to provide."]},{"k":"p","s":["If you’re a British passport holder with links to Azerbaijan, through birth or otherwise, and need to check your nationality status, contact the ",["State Migration Service","https://migration.gov.az/en"]," before you travel."]},{"k":"hs","s":["Checks at border control"]},{"k":"p","s":["Anyone who has previously visited certain areas in south-western Azerbaijan, including the town of Khankendi, without the permission of the Azerbaijani authorities could be denied entry to Azerbaijan. You should contact the nearest embassy or consulate of Azerbaijan before you travel. See ",["Regional Risks","https://www.gov.uk/foreign-travel-advice/azerbaijan/regional-risks"],"."]},{"k":"h","s":["Entry via land or sea borders"]},{"k":"p","s":["You can only enter Azerbaijan via air travel without restrictions. Entry via a land or sea border is restricted. Once in Azerbaijan you can exit via air or sea routes. If you want to leave Azerbaijan by road, you need permission from the authorities."]},{"k":"h","s":["Entering with a vehicle"]},{"k":"p","s":["To enter Azerbaijan with a vehicle, you need to arrange for the vehicle to be shipped to Baku, where you have to arrange for collection at Customs. You need to provide Power of Attorney and pay fees as required."]},{"k":"h","s":["Borders with Iran and Georgia"]},{"k":"p","s":["The land borders between Iran and Azerbaijan, and Georgia and Azerbaijan are temporarily closed."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit Azerbaijan."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["You can apply and pay for a visa from the ",["ASAN Visa (e-visa) service","https://evisa.gov.az/en/"],". Apply at least 3 days in advance. An urgent 3-hour service is available for an additional fee."]},{"k":"p","s":["E-visas are normally single entry and allow a 30-day visit within a 90-day period of validity. You must print out the e-visa and bring it with your passport to show on arrival. Officials will check that your passport is valid for 3 months after the visa expiry date. This means your passport must be valid for at least 6 months after the date you arrive in Azerbaijan."]},{"k":"p","s":["For other types of visas, such as a business visa or a work permit, contact the ",["Azerbaijani Embassy in the UK","https://london.mfa.gov.az/en"]," at least one month before your travel date."]},{"k":"hs","s":["FIFA U-15 World Cup and Festival 2026"]},{"k":"p","s":["If you are travelling to Azerbaijan for the FIFA U-15 World Cup and Festival 2026, ",["simplified visa arrangements","https://london.mfa.gov.az/en/category/facilated-visa-procedures-for-the-fifa-u-15-world-cup-festival-2026"]," are in place from 22 September to 5 November 2026. Eligible travellers can obtain a visa on arrival at Azerbaijan’s international airports. You must have either an official invitation letter from the Association of Football Federations of Azerbaijan (AFFA) or confirmation of accreditation through FIFA’s electronic registration system."]},{"k":"hs","s":["Travelling on a UK Emergency Travel Document"]},{"k":"p","s":["Azerbaijan accepts UK Emergency Travel Documents (ETDs) for entry and must be accompanied by a visa to enter Azerbaijan. You cannot use a UK ETD to apply for an Azerbaijani e-visa, as the e-visa system does not recognise ETDs as eligible travel documents. If you are travelling on a UK ETD, you must apply for a visa directly through an Azerbaijani embassy before you travel. Contact the Azerbaijani Embassy in the country where you are applying for advice on the application process and processing times."]},{"k":"hs","s":["Extending your visa"]},{"k":"p","s":["You can extend your 30 days by applying to the ",["State Migration Service","https://migration.gov.az/en/page/72"]," at least 3 days before the end of the permitted stay."]},{"k":"p","s":["If you overstay your visa without permission, you may have to leave the country within 48 hours. Contact the ",["State Migration Service","https://migration.gov.az/en/contact/59"]," as soon as possible. They can issue a letter giving you permission to leave. You will have to pay a fine of 300 to 400 Azerbaijani manat. Make sure you get a receipt as proof of payment."]},{"k":"p","s":["If you are in Azerbaijan, you can also call the Migration Information Centre on 919."]},{"k":"hs","s":["Registering with the authorities"]},{"k":"p","s":["If you’re staying in Azerbaijan for longer than 15 days, you must ",["register with the State Migration Service","https://eservice.migration.gov.az/?lang=en"]," online or in person. If you do not register you will have to pay a fine to the ",["State Migration Service","https://migration.gov.az/en/contact/59"]," before you are able to leave the country. Hotels often provide this service for their guests, but you must do it yourself if you are staying in an apartment or private residence."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Azerbaijan guide","https://travelhealthpro.org.uk/country/17/azerbaijan#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Azerbaijan. You must declare anything that may be prohibited or subject to tax or duty. Follow advice from your airline about items you should declare."]},{"k":"p","s":["If you plan to use a local SIM card for more than 30 days, you must register it and pay a fee at a local post office. If you do not declare your device or register your sim card, it may not work on local networks and your device could be locked. You will need to give the IMEI number of your mobile, which you can find in settings, or by dialling *#06#."]},{"k":"hs","s":["Exporting carpets and antiques"]},{"k":"p","s":["You need an export certificate to take antiques or art like carpets, samovars, copperware or paintings out of Azerbaijan. Your vendor will give you a certificate, or they are available from the ",["Azerbaijan National Carpet Museum","https://azcarpetmuseum.az/en/contact"],"."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of Azerbaijan","https://www.gov.uk/foreign-travel-advice/azerbaijan/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Azerbaijan"]},{"k":"p","s":["Terrorists are likely to try to carry out attacks in Azerbaijan."]},{"k":"p","s":["Terrorism attacks could be indiscriminate, including in places visited by foreign nationals, such as:"]},{"k":"li","s":["hotels, restaurants and pubs"]},{"k":"li","s":["energy sector facilities"]},{"k":"li","s":["religious sites and places of worship"]},{"k":"li","s":["shopping centres and crowded places"]},{"k":"li","s":["embassies and government buildings"]},{"k":"li","s":["sporting and cultural events"]},{"k":"li","s":["transport hubs"]},{"k":"p","s":["Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["The political situation in Azerbaijan is generally calm, but demonstrations and opposition rallies can occur."]},{"k":"p","s":["Avoid large gatherings and any demonstrations. They are illegal and there could be a swift response from the authorities. Monitor the media for information about possible demonstrations and be alert to local and regional developments, which may trigger public disturbances."]},{"k":"p","s":["If you are a British journalist, make sure you are clearly identifiable."]},{"k":"hs","s":["Armenia-Azerbaijan tensions"]},{"k":"p","s":["Tensions between Armenia and Azerbaijan have calmed and the risk of further conflict has decreased, including in the areas of those regions affected by conflict in 2020 and 2023. The FCDO continues to advise against all but essential travel to some areas in south-western Azerbaijan due to the risks from mines or unexploded ordnance from former conflict, and advises against all travel within 5km of the border with Armenia. See ",["Regional Risks","https://www.gov.uk/foreign-travel-advice/azerbaijan/regional-risks"],"."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Crime levels in Baku are generally low. Be alert to possible bag-snatching or mugging, particularly if you are carrying large amounts of cash or valuables. The risk is higher after dark in the centre of town. Avoid displaying large sums of money or expensive-looking valuables and do not walk alone at night."]},{"k":"hs","s":["Dealing with officials"]},{"k":"p","s":["There are occasionally reports of government officials asking foreign nationals to make undocumented payments. If you think you have been mistreated by a traffic policeman or health professional, report your case to the relevant government department."]},{"k":"hs","s":["Bank card fraud"]},{"k":"p","s":["Fraudsters can steal your card details without you noticing. Take extra care to guard against card skimming when using credit cards or withdrawing cash from ATMs. Use ATMs inside banks where possible, check street ATMs for signs of tampering, and always keep your card in sight when paying in shops and restaurants."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"p","s":["Azerbaijan is a largely secular society, although most of the population is Muslim. Religion is usually considered a private matter."]},{"k":"p","s":["Some areas, such as Martyrs’ Alley, are especially sensitive. Disruptive or disrespectful conduct in or around such area may result in police action, including fines or being summoned to the police station."]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Police sometimes carry out checks of identity documents. Carry your passport at all times. Keep a copy of the photo page in a safe place."]},{"k":"hs","s":["Dress code"]},{"k":"p","s":["In Baku local and foreign women usually dress in conservative western-style clothing. It is now more acceptable for men to wear shorts in Baku in the summer months. Outside of Baku it may still be frowned on, and you may receive unwelcome attention."]},{"k":"hs","s":["Ramadan"]},{"k":"p","s":["Ramadan is a holy month for Muslims. The dates vary by year and country."]},{"k":"p","s":["Most restaurants, cafés, shops and other services in Azerbaijan continue to operate during Ramadan. Some businesses may adjust their opening hours or offer special Ramadan arrangements."]},{"k":"p","s":["During Ramadan, you should:"]},{"k":"li","s":["check opening hours of shops and restaurants, as these may vary"]},{"k":"li","s":["respect local religious customs and traditions"]},{"k":"li","s":["follow local dress codes, particularly when visiting religious sites - clothing that does not meet local dress codes may cause more offence at this time"]},{"k":"li","s":["be aware that some people may be fasting and may be more tired than usual, especially in the late afternoon and early evening"]},{"k":"li","s":["be patient and considerate towards those who are observing Ramadan"]},{"k":"hs","s":["Smoking restrictions"]},{"k":"p","s":["Smoking is restricted to designated areas. You can be fined for dropping smoking-related litter. Use bins provided."]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["Possession or use of illegal drugs, including cannabis, carries severe penalties. You should expect a long jail sentence and heavy fines for possessing, using, or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["Airports in Azerbaijan have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Using cameras and drones in sensitive locations"]},{"k":"p","s":["Be aware of cultural sensitivities when photographing mosques, churches and other religious sites or sites of commemoration, such as the Alley of Martyrs in Baku. If in doubt, ask for permission."]},{"k":"p","s":["Military bases, equipment and installations in any condition are considered sensitive areas, and visitors have been detained and questioned while attempting to visit or photograph them."]},{"k":"p","s":["If you do not have temporary or permanent residence rights in Azerbaijan, you are not allowed to import drones. Any drones will be confiscated by the State Customs Office at the port or border and returned upon departure."]},{"k":"p","s":["Unmanned drones cannot be rented to individuals without a valid taxpayer identification number (TIN). If you have a TIN, special permission from the ",["Ministry of Digital Development and Transport","https://mincom.gov.az/en"]," is required. Manned drones can be rented without requiring permission."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["While same-sex sexual activity is not illegal, LGBT+ people in Azerbaijan tend to keep a low profile. Showing affection in public is frowned upon, especially outside of Baku and among the older generation."]},{"k":"p","s":["Holding hands or embracing between men is usually a sign of friendship."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Azerbaijan, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and read the ",["RAC guide on driving in Azerbaijan","https://www.rac.co.uk/drive/travel/country/azerbaijan/"],". The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["It is illegal to use right-hand-drive cars in Azerbaijan."]},{"k":"hs","s":["Inter-country road travel"]},{"k":"p","s":["There may be delays in transporting vehicles to Azerbaijan. It is best not to pay for non-refundable onward travel. Azerbaijan Caspian Shipping Closed Joint-Stock Company has ",["details of onward shipment from Baku to Turkmenistan and Kazakhstan","https://www.asco.az/en/pages/2/96"],"."]},{"k":"hs","s":["Licences and permits"]},{"k":"p","s":["You’ll need to have both the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and your UK driving licence with you in the car. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["After one month, you will need an Azerbaijani driving licence issued through the ",["ASAN Service Offices","https://asan.gov.az/en"],". You need to carry a ",["green card","https://www.gov.uk/vehicle-insurance/driving-abroad"]," as proof you’re insured to drive in Azerbaijan."]},{"k":"p","s":["If you’re planning to hire a car, check with your car hire company for information on their requirements before you travel."]},{"k":"hs","s":["Driving conditions"]},{"k":"p","s":["Many vehicles are poorly maintained, and the standard of driving is erratic. Accidents are common, mainly due to poor or reckless driving and inconsistent enforcement of traffic rules. Drivers often ignore one-way signs."]},{"k":"p","s":["Road closures and diversions are often unmarked. Take care when driving at night as many roads are of poor quality and badly lit. Traffic lights that are flashing amber at night mean cars can proceed with caution in either direction."]},{"k":"p","s":["Drink-driving is a serious offence in in Azerbaijan. If you are tested and found to have any alcohol in your system, you may get a severe fine and possibly a prison sentence."]},{"k":"p","s":["In the winter months snowfall often causes problems. Pack your vehicle with a blanket, shovel, torch, snacks and old carpet to help if you get stuck in snow."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Try to arrange to be picked up and dropped off as close to your hotel or apartment entrance as possible by a private or company driver, or use a known firm or taxi app."]},{"k":"p","s":["Some visitors have reported being severely overcharged by local taxis. When using taxis, agree a fare up front, or make sure the taxi meter is switched on. Check that the taxi has working seatbelts."]},{"k":"p","s":["Ride-hailing apps such as Uber and Bolt are widely available in Azerbaijan."]},{"k":"hs","s":["Rail travel"]},{"k":"p","s":["If you travel by train, secure your valuables, do not leave the compartment unattended, and lock the door from the inside, if your compartment allows."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["There is a risk of earthquakes across the Caucasus region, although there have been no recent serious earthquakes in Azerbaijan. The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Azerbaijan. It only covers regions where the Foreign, Commonwealth & Development Office (FCDO) has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/azerbaijan"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/azerbaijan/safety-and-security"],"."]},{"k":"hs","s":["South-western Azerbaijan (those regions affected by conflict in 2020 and 2023)"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) advises against all but essential travel to some areas in south-western Azerbaijan, including districts in and around the region formerly known as “Nagorno-Karabakh” due to the risks from leftover military equipment and weapons from former conflict. This includes:"]},{"k":"li","s":["the districts (‘rayons’) of Kelbajar, Lachin, Qubadli, Zengilan, Jabrayil, Fuzuli, Khojavand, Shusha, Khojali, Khankendi, Aghdam and Tartar"]},{"k":"p","s":["It is illegal to enter certain areas in south-western Azerbaijan, without the permission of the Azerbaijani authorities. Anyone who has previously visited these areas, including the town of Khankendi, without the permission of Azerbaijani authorities could be denied entry to Azerbaijan. You should contact the nearest embassy or consulate of Azerbaijan before you travel."]},{"k":"p","s":["Whilst tensions have calmed and the risk of further conflict has decreased, there remains a risk of unexploded weapons and landmines in south-western Azerbaijan. The Azerbaijani authorities are working to remove unexploded weapons and landmines."]},{"k":"p","s":["Follow Azerbaijani national government and local authorities’ advice in areas that have not been cleared of mines or unexploded ordnance. If you come across an unexploded weapon or landmine do not approach it or touch it. Make a note of where you saw it and notify the authorities on 102 or 112. Beware of more unexploded weapons or landmines nearby."]},{"k":"h","s":["Azerbaijan-Armenia border"]},{"k":"p","s":["The border with Armenia remains closed. The FCDO also advises against all travel to within 5km of the rest of the border with Armenia. Note that this does not include the border of Azerbaijan’s Nakhchivan exclave with Armenia."]},{"k":"h","s":["Azerbaijan-Russia border"]},{"k":"p","s":["The land border between Azerbaijan and Russia (Dagestan) is closed. The FCDO continues to advise against all travel to Russia. For further details, see ",["FCDO’s travel advice for Russia","https://www.gov.uk/foreign-travel-advice/russia"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 103 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Azerbaijan","https://travelhealthpro.org.uk/country/17/azerbaijan#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["Go to TravelHealthPro to see ",["what health risks you’ll face in Azerbaijan","https://travelhealthpro.org.uk/country/17/azerbaijan"],"."]},{"k":"p","s":["Altitude sickness is a risk in some parts of Azerbaijan, including the ski resorts of Shahdag and Tufangdag in the Gusar district, Lake Batabat in Nakhchivan, and the Talysh mountains. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare facilities in Azerbaijan"]},{"k":"p","s":["Medical facilities outside Baku are very limited. Carry a comprehensive first aid kit for any trips out of Baku. Even in Baku, serious illness or injury may require evacuation to Turkey or Western Europe. Make sure you have appropriate travel health insurance."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Azerbaijan","https://www.gov.uk/government/publications/azerbaijan-list-of-medical-facilitiespractitioners"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Azerbaijan"]},{"k":"p","s":["Ambulance: 103"]},{"k":"p","s":["Fire: 101"]},{"k":"p","s":["Police: 102"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=azerbaijan"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=azerbaijan"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=azerbaijan"]," in Azerbaijan"]},{"k":"li","s":["dealing with a ",["death in Azerbaijan","https://www.gov.uk/government/publications/azerbaijan-bereavement-information"]]},{"k":"li","s":["being ",["arrested or imprisoned in Azerbaijan","https://www.gov.uk/government/publications/azerbaijan-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/azerbaijan/british-embassy-baku"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/azerbaijan/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Azerbaijan","https://www.gov.uk/government/publications/overseas-business-risk-azerbaijan"]," on how to manage political, economic, and business security-related risks."]}],"chars":25491,"change":"New information about entry requirements for the upcoming FIFA U-15 World Cup and Festival 2026 and travelling on a UK Emergency Travel Document to Azerbaijan. Updated information about visa requirements and entering Azerbaijan across the land border from Iran ('Entry requirements' page)."},"https://www.gov.uk/foreign-travel-advice/bulgaria":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"1a10ecf3da2abcb27de19ce9c4b6daab916b5a296cca9234124db96c3589a81e","read":"https://www.gov.uk/api/content/foreign-travel-advice/bulgaria","bytes":78474,"x":"fulltext v1","title":"Bulgaria travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-20T00:00:00+00:00","mod":"2026-08-11T10:18:49+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/bulgaria/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/travelaware/"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Bulgaria set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the Bulgarian Embassy in the UK."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Bulgaria follows ",["Schengen area rules","https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm"],". Your passport must have:"]},{"k":"li","s":["have a ‘date of issue’ less than 10 years before the date you arrive – if you renewed your passport before 1 October 2018, it might have a date of issue that is more than 10 years ago, making it invalid for entry to the Schengen area"]},{"k":"li","s":["an ‘expiry date’ at least 3 months after the date you plan to leave the Schengen area (the expiry date does not need to be within 10 years of the date of issue)"]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"p","s":["Carry your passport if you travel from Bulgaria to other Schengen area countries. Border guards may check it if you cross land or river borders into Greece or Romania, both in the Schengen area."]},{"k":"p","s":["There are no routine checks when travelling by air or sea within the Schengen area, but carry your passport in case you’re asked for it. Most carriers require official photo ID."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can ",["travel without a visa to the Schengen area","https://www.gov.uk/travel-to-eu-schengen-area"],", which includes Bulgaria, for up to 90 days in any 180-day period. This applies if you travel:"]},{"k":"li","s":["as a tourist"]},{"k":"li","s":["to visit family or friends"]},{"k":"li","s":["to attend business meetings, cultural or sports events"]},{"k":"li","s":["for short-term studies or training"]},{"k":"p","s":["The ",["requirements for working in Bulgaria","https://www.gov.uk/guidance/travel-to-bulgaria-for-work"]," are different."]},{"k":"p","s":["If you’re travelling to other Schengen countries as well, make sure your whole visit is within the 90-day visa-free limit. Visits to Schengen countries in the 180 days before you travel count towards your 90 days. If you overstay the 90-day visa-free limit, you may be banned from entering Schengen countries for up to 3 years."]},{"k":"p","s":["At Bulgarian border control, you may also need to:"]},{"k":"li","s":["show proof of your accommodation, for example, a hotel booking confirmation or proof of address for a second home"]},{"k":"li","s":["show proof of your travel insurance"]},{"k":"li","s":["show a return or onward ticket"]},{"k":"li","s":["prove that you have enough money for your stay – the amount varies depending on your accommodation"]},{"k":"hs","s":["Staying longer than 90 days in a 180-day period"]},{"k":"p","s":["To stay longer, check which type of visa or work permit you need with the Bulgarian Embassy in the UK."]},{"k":"p","s":["If you’re in Bulgaria with a residence permit or long-stay visa, this does not count towards your 90-day visa-free limit."]},{"k":"p","s":["Read about ",["entry processes if you live in Bulgaria","https://www.gov.uk/guidance/living-in-bulgaria#passports-and-travel"],"."]},{"k":"h","s":["New Schengen entry requirements"]},{"k":"p","s":["The European Union’s (EU) new Entry/Exit System (EES) is now being implemented across the Schengen area."]},{"k":"p","s":["This means that when you travel into the Schengen area for short stays, you may need to register your biometric details, such as fingerprints and a photo. There is no cost for EES registration."]},{"k":"p","s":["On your first visit into a Schengen country, you may be asked to register your details at a special booth before proceeding to the immigration desk. Follow directions from your travel operator or the staff at your port of entry. You may also need to provide either your fingerprint or photo when you leave the Schengen area. Children aged 11 or younger will not have their fingerprints scanned but can be required to have their photo taken."]},{"k":"p","s":["You do not need to take any action before you arrive at the border on entry to the Schengen area, but EES may take each passenger extra time to complete so be prepared to wait longer than usual at the border and to allow more time for immigration controls when you depart the Schengen area. If you are departing the Schengen area by plane, allow extra time to reach your departure gate as EES checks may take place before boarding."]},{"k":"p","s":["EES is replacing the previous system of manually stamping passports when visitors arrive in the Schengen area for short stays. You may be asked to input biometric details every time you enter or exit."]},{"k":"p","s":["If you enter the Schengen area through the Port of Dover, Eurotunnel at Folkestone or Eurostar at St Pancras International, any information will be taken at the border before you leave the UK."]},{"k":"p","s":["Your digital EES record is valid for 3 years."]},{"k":"p","s":["Read more ",["information on the EU Entry/Exit System and to understand which countries are in the Schengen area","https://www.gov.uk/guidance/eu-entryexit-system"],"."]},{"k":"p","s":["If you are long-term resident in a Schengen country, you are exempt from EES in all Schengen countries. The full list of EES exemptions is on ",["the EU’s official Travel Europe website.","https://travel-europe.europa.eu/en/ees/to-whom-does-ees-not-apply"]]},{"k":"p","s":["If you believe you have been incorrectly entered into EES or your record of time spent in the Schengen area is incorrect, approach border officials when you next cross the Schengen border and request a correction. If you are exempt, carry documentation confirming your status. If you believe your time spent in the Schengen area has been recorded incorrectly, raise this with border officials and be prepared to provide supporting evidence if requested."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Bulgaria guide","https://travelhealthpro.org.uk/country/36/bulgaria#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Bulgaria","https://customs.bg/wps/portal/agency-en/home/info-citizens/Important%20notice%20for%20travelers"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking food and drink into Bulgaria"]},{"k":"p","s":["You cannot take ",["meat, milk or products containing them into EU countries","https://ec.europa.eu/food/animals/animalproducts/personal_imports_en"],". There are some exceptions such as powdered baby milk, baby food and special foods or pet feed required for medical reasons."]},{"k":"hs","s":["Taking money into Bulgaria"]},{"k":"p","s":["As of 1 January 2026, the currency of Bulgaria will be the euro. Bulgarian lev will still be accepted until 31 January, but can be exchanged for euros free of charge at Bulgarian banks until 30 June 2026."]},{"k":"p","s":["There may be some temporary disruption to card payments and to cash withdrawals from ATMs around 31 December 2025 to 1 January 2026 due to the changeover in currency. Cash payments will be unaffected."]},{"k":"p","s":["Major credit and debit cards are accepted in most banks and hotels. Most ATMs accept standard international credit and debit cards."]},{"k":"p","s":["Pounds sterling and US dollars are easily exchanged for euros. Only exchange money at reliable places such as banks and currency exchange bureaux."]},{"k":"p","s":["Declare ",["cash or travellers cheques if the value is 10,000 euros or more","https://customs.bg/wps/portal/agency-en/home/info-citizens/Carrying%20of%20cash,%20precious%20metals,%20gems%20and%20items%20containing%20them%20or%20made%20of%20them"],". You will get a certified declaration to show you brought it in with you. If you do not, your money could be seized when you leave."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Bulgaria"]},{"k":"p","s":["Although there’s no recent history of terrorism in Bulgaria, attacks cannot be ruled out."]},{"k":"p","s":["Attacks could be indiscriminate, including in places visited by foreign nationals. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Protests and demonstrations"]},{"k":"p","s":["There are occasional political protests in towns and cities across Bulgaria. They can cause disruption to transport as protestors or police may set up roadblocks. Most protests are peaceful but there have been occasional incidents of violence, including by the police. Avoid all protests and follow the advice of local authorities."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Take sensible precautions to protect yourself from street crime, particularly in larger cities and late at night. Beware of any attempts to distract you. Watch out for pickpockets and bag thefts in tourist areas, on buses and trains and major public transport hubs, including airports."]},{"k":"p","s":["Thefts from unattended cars at petrol stations have increased. Lock your car when going inside the petrol station to pay for your fuel."]},{"k":"p","s":["Tourists are targeted by thieves and pickpockets in Sunny Beach and other larger cities and resorts. Thefts on the bus from Nessebar to Sunny Beach have also increased. Do not take valuables to the beach and be wary of poorly lit roads around the resort at night."]},{"k":"hs","s":["Scams"]},{"k":"p","s":["Some tourists have been the victims of overcharging in so-called ‘gentlemen’s clubs’ in Sofia and in some resorts including Bansko, Borovets and Sunny Beach. Overcharging can amount to hundreds of pounds. Victims can be threatened with violence if they refuse to pay."]},{"k":"p","s":["Get recommendations for bars and clubs from your hotel or other holidaymakers. When paying by card make sure the transaction is completed in your presence and be wary if asked to re-enter your PIN."]},{"k":"hs","s":["Thefts from accommodation"]},{"k":"p","s":["There have been burglaries from hotel rooms in Sunny Beach. Make sure you lock your room (including windows and balcony doors) and keep valuables locked in a safe."]},{"k":"p","s":["There have been break-ins at properties in the residential areas of cities, and rural areas."]},{"k":"hs","s":["Thefts from cars"]},{"k":"p","s":["Criminals may puncture your tyres or flag down your car. When you get out, the thieves can distract you and steal from your vehicle. Make sure the boot is locked and your luggage is secure."]},{"k":"hs","s":["Property fraud"]},{"k":"p","s":["Buyers have been defrauded while buying property. Be cautious and get legal advice before you buy. Only deal with established and reputable real estate agents or with other contacts who you know to be reliable and genuine."]},{"k":"p","s":["See ",["more details about buying property","https://www.gov.uk/guidance/living-in-bulgaria#accommodation-and-buying-property"],"."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry ID. A printed copy of the photo page of your passport is acceptable."]},{"k":"hs","s":["Illegal drugs and sex offences"]},{"k":"p","s":["The Bulgarian authorities treat all drug-related and sex offences very seriously. Any foreign nationals convicted of such offences can expect a prison sentence. Illegal drugs, including cannabis, carry severe penalties. You should expect a long jail sentence and heavy fines for possessing, using, or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["Airports in Bulgaria have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Drunken and disorderly behaviour"]},{"k":"p","s":["Offences relating to drunken, disorderly behaviour and hooliganism may be treated more seriously than in the UK. Police can arrest or fine anyone for loud and boisterous behaviour or urination in public places."]},{"k":"hs","s":["Football matches"]},{"k":"p","s":["Crowd control measures and stewarding can be different from the UK and there have been a small number of incidents where ‘throwdown fireworks’ such as firecrackers or bangers have been set off in stadiums, risking injuries. Stay aware of your surroundings and be alert in crowded venues."]},{"k":"hs","s":["Using cameras and binoculars in secure areas"]},{"k":"p","s":["Avoid taking photographs near potentially sensitive areas like military establishments. If in doubt, ask permission."]},{"k":"hs","s":["Working with migrants in border regions"]},{"k":"p","s":["Assisting people who have entered Bulgaria illegally, or who are passing through Bulgaria to claim asylum in another country, risks breaking Bulgarian laws. It makes no difference whether you are helping them for profit or not – you are still at risk of breaking Bulgarian law. You can be arrested, detained and charged if you are suspected of facilitating illegal entry or stay in Bulgaria, including by helping with accommodation or transport. If you travel to Bulgaria to support civil society organisations working with migrants, seek advice from local expert organisations such as the ",["IOM","https://bulgaria.iom.int/"],", ",["UNHCR","https://www.unhcr.org/countries/bulgaria"]," or ",["Bulgarian Helsinki Committee","https://www.bghelsinki.org/en"]," to make sure that your proposed actions do not break Bulgarian laws."]},{"k":"hs","s":["Race-related incidents"]},{"k":"p","s":["The majority of visitors experience no difficulties related to their race, ethnicity or religious beliefs. However there have been a small number of verbal and physical attacks against ethnic minority UK nationals, including residents, in Bulgaria, and others have experienced unwanted attention or harassment in public places."]},{"k":"p","s":["Instances have increased at times of demonstrations organised by groups connected to populist or right-wing movements. Avoid all protests and stay aware of your surroundings, particularly when travelling alone or at night."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is not illegal, but public attitudes are less tolerant than in the UK and the LGBT+ community generally keeps a low profile."]},{"k":"p","s":["There are a few gay bars and clubs in Sofia. The city also holds the annual Sofia Pride. Sofia Pride is growing in popularity and was attended in recent years by over 10,000 people. However, it attracts some negative attention locally and is held with a heightened police presence and security measures. If you want to join the parade, read the organisers’ Sofia Pride safety rules."]},{"k":"p","s":["In recent years, some verbal abuse and threatening behaviour was directed at people attending events related to Sofia Pride, including foreign visitors. You can report any hate crime to the organisers and the local police."]},{"k":"p","s":["Attitudes outside Sofia tend to be more conservative. There have been isolated cases of hostility towards people perceived to be from LGBT+ communities reported in Burgas and Plovdiv. You can find local information on LGBT+ issues in Bulgaria on the website of the ",["Bulgarian Helsinki Committee","https://www.bghelsinki.org/en/themes/lgbti"],"."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Face-covering ban"]},{"k":"p","s":["Covering your face with a niqab, burka or similar head covering in public places is illegal in Bulgaria and police could give you a fine. This applies in public buildings, streets, parks, restaurants, shops and on public transport."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"p","s":["Sports activities like skiing, potholing and mountaineering, and sports classed as particularly dangerous – mountain biking, climbing, paragliding or BASE jumping – all carry risks. Your insurance should include:"]},{"k":"li","s":["mountain rescue services"]},{"k":"li","s":["helicopter costs"]},{"k":"li","s":["repatriation to your home country or possible transfer to neighbouring countries for treatment"]},{"k":"p","s":["There’s more ",["information about mountain insurance","https://en.redcross.bg/activities/activities2"]," on the Bulgarian Red Cross website."]},{"k":"hs","s":["Quad biking and motorbikes"]},{"k":"p","s":["Quad biking is an extreme sport and carries the risk of serious injury or death. You need specific travel insurance to cover quad biking. Always read the details of your insurance cover, especially the small print and exclusions on your policy."]},{"k":"p","s":["Make sure you are given full instructions and training before your activity."]},{"k":"p","s":["Insurance sold by the hire company usually only provides third-party insurance. It’s likely you will be charged for any damage to the rental vehicle and you may face arrest if you do not pay."]},{"k":"p","s":["If you hire a motorbike, you need a full motorbike licence. Make sure the vehicle is in good condition. Drivers and passengers must wear helmets. Failure to do so may invalidate your insurance."]},{"k":"hs","s":["Swimming and water sports"]},{"k":"p","s":["Obey any warning signs at coastal areas and beaches. Follow instructions from lifeguards and observe the flag indicators if they are present. Follow local advice if jellyfish or sea urchins are present."]},{"k":"p","s":["For more advice, see ",["Water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"p","s":["Book activities at a licensed water sports centre and before you start:"]},{"k":"li","s":["make sure the paperwork is completed"]},{"k":"li","s":["ask for a safety demonstration"]},{"k":"li","s":["make sure you know how to call for help"]},{"k":"p","s":["See ⁠ ",["watersports safety advice","https://www.rospa.com/leisure-water-safety/water/advice/watersports-abroad"]," from the Royal Society for the Prevention of Accidents (ROSPA)."]},{"k":"hs","s":["Winter sports"]},{"k":"p","s":["Read advice about ",["preparing for winter sports abroad","https://www.gov.uk/guidance/winter-sports-stay-safe-on-the-slopes"],". The Bulgarian Mountain Rescue service publishes ",["safety rules on the ski slopes","https://www.pss-bg.bg/pravila-za-bezopasnost-po-ski-pistite/"]," (in Bulgarian)."]},{"k":"p","s":["Avalanches are a risk in some areas. Always check the local snow and weather conditions if you plan to ski off-piste, and ski with a guide. There’s more information about avalanche risk from the ",["Bulgarian Mountain Rescue Service","https://www.pss-bg.bg/"]," (in Bulgarian)."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you plan to drive in Bulgaria, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and check the ",["rules of the road in the RAC’s Bulgaria guide","https://www.rac.co.uk/drive/travel/country/bulgaria/"],". The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["If you bring your own car to Bulgaria, you must have:"]},{"k":"li","s":["your driving licence"]},{"k":"li","s":["all original registration and ownership documents"]},{"k":"li","s":["proof of insurance that is valid in Bulgaria – although you are not required to have a green card to drive in Bulgaria, you may need it in some neighbouring countries"]},{"k":"p","s":["Check if you need a ",["UK sticker to drive your car outside the UK","https://www.gov.uk/displaying-number-plates/flags-identifiers-and-stickers"],"."]},{"k":"p","s":["If it’s a hired car, you must keep the contract document. Border officials will impound your vehicle if they are not satisfied that you own it or have permission to use it in Bulgaria."]},{"k":"p","s":["Vehicles that are registered outside the EU are considered to be ‘temporarily imported’ when driven inside Bulgaria. If your car is stolen in Bulgaria, you will be liable for import duty and related taxes."]},{"k":"p","s":["See ",["driving requirements if you live in Bulgaria","https://www.gov.uk/guidance/living-in-bulgaria#driving-in-bulgaria"],"."]},{"k":"hs","s":["Driving conditions"]},{"k":"p","s":["Road conditions can be dangerous. Take care when driving, particularly at night and outside major cities. Many roads (and pavements) are in poor repair and roadworks are often unmarked and unlit at night. Driving standards are generally poor, and drivers can be aggressive, particularly on motorways. Avoid confrontations."]},{"k":"p","s":["There may be slow-moving cars and animal-drawn vehicles on the roads, particularly in rural areas."]},{"k":"p","s":["You must drive with side lights or dipped headlights, even during the daytime. Keep to the speed limit and make sure your vehicle is roadworthy. Traffic police issue on-the-spot fines for minor violations."]},{"k":"p","s":["Bulgaria has strict penalties for driving under the influence of alcohol and drugs, and doing so could lead to vehicle confiscation, a prison sentence and fines. If you receive a penalty and do not own the vehicle, you could be required to pay a fine equivalent to the vehicle’s value."]},{"k":"hs","s":["Tolls"]},{"k":"p","s":["If you want to use motorways and main roads outside towns, you’ll need to buy a digital vignette in advance of your journey. The vignette is a form of toll. If you use the roads without a vignette, traffic police will issue a fine. You can ",["buy a vignette online","https://www.tolltickets.com/en/country/bulgarien/"],"."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Taxis may not be in very good condition. Avoid taxis parked outside hotels or in tourist areas. Ask your hotel to call a taxi or flag down a passing taxi with a green ‘available’ light in the window. Check the licence sticker and the tariffs on the window before getting in as costs can vary considerably. Licensed taxis run by ‘Yellow’ operators are the most reliable."]},{"k":"p","s":["There are regular reports of robberies and threatening behaviour by taxi drivers in Sunny Beach. Use a taxi recommended by your tour operator or accommodation provider."]},{"k":"p","s":["There has been an increase in unlicensed taxis from Sofia airport overcharging passengers. If you’re travelling from the airport, make sure you take an official, licensed taxi. There is an ",["official taxi booking office","https://sofia-airport.eu/en/access/transportation/#by-taxi"]," in the arrivals hall. Check that the taxi meter is working before starting your journey."]},{"k":"hs","s":["Rail and bus travel"]},{"k":"p","s":["Thieves operate on trains. Make sure that documents and valuables are safe. The train system is very poor by European standards. There have been several fires on Bulgarian trains. Bulgaria has a comprehensive rail network, but trains can be cancelled at short notice. For travel updates see the ",["Bulgaria Railways website","https://www.bdz.bg/en"],"."]},{"k":"p","s":["The roadworthiness of vehicles and driving standards are not always good, and there have been a number of serious accidents in recent years."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["In summer and early autumn, Bulgaria is on a regular alert for wildfires. There is danger of large-scale and quick-spreading fires in forests and fields. Follow media reports and the advice of local authorities if wildfires occur in your area."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Many parts of Bulgaria flood following heavy rains. Flooding is usually localised but can occasionally be widespread and has caused deaths. Watch for weather warnings on the National Institute of Meteorology and Hydrology website."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["There are earthquakes and small tremors throughout the year, usually without serious consequences. The last significant earthquakes were in 1928."]},{"k":"p","s":["The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 112 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Bulgaria","https://travelhealthpro.org.uk/country/36/bulgaria#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Bulgaria","https://travelhealthpro.org.uk/country/36/bulgaria"],", including biting insects and ticks."]},{"k":"p","s":["Altitude sickness is a risk in parts of Bulgaria. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"hs","s":["Stray dogs"]},{"k":"p","s":["Stray dogs are common and can be dangerous. Avoid getting too close to dogs, especially if they are in a pack. Take any animal bites seriously and seek immediate medical advice as rabies and other animal-borne diseases are present in Bulgaria."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Bulgaria"]},{"k":"p","s":["FCDO has a list of ",["medical providers in Bulgaria","https://www.gov.uk/government/publications/bulgaria-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"p","s":["Most Bulgarian hospitals are basic and old-fashioned compared to those in the UK. Standards of medical care are generally good, but specialised equipment and treatment may not be available. Hospital staff rarely speak English."]},{"k":"p","s":["Private clinics and hospitals are generally well-equipped and not expensive in comparison with the UK."]},{"k":"p","s":["Foreign tourists have sometimes been overcharged in private clinics in tourist resorts. Hotels or resorts may call private ambulances. If you use private medical services, agree a price in advance. Ask whether there is a suitable public health facility nearby if you want to use a health insurance card, as these are not accepted by many private hospitals."]},{"k":"hs","s":["Health insurance cards"]},{"k":"p","s":["To get medically necessary state healthcare in Bulgaria, you need a Global Health Insurance Card (GHIC) or a European Health Insurance Card (EHIC)."]},{"k":"p","s":["The NHS’s ",["getting healthcare abroad webpage","https://www.nhs.uk/using-the-nhs/healthcare-abroad/apply-for-a-free-uk-global-health-insurance-card-ghic/"]," has details about:"]},{"k":"li","s":["how to apply for a GHIC"]},{"k":"li","s":["how to get temporary cover if you lose your card or it does not arrive in time"]},{"k":"li","s":["who qualifies for a new EHIC instead of a GHIC"]},{"k":"li","s":["what treatment counts as medically necessary"]},{"k":"p","s":["A GHIC or EHIC is not an alternative to travel insurance. You may have costs your GHIC or EHIC does not cover, including:"]},{"k":"li","s":["changes to travel and accommodation bookings"]},{"k":"li","s":["additional standard costs for treatment"]},{"k":"li","s":["medical repatriation to the UK"]},{"k":"li","s":["treatment that is ruled non-urgent"]},{"k":"li","s":["private healthcare"]},{"k":"li","s":["private clinics"]},{"k":"p","s":["Read about ",["healthcare if you live in Bulgaria","https://www.gov.uk/guidance/healthcare-in-bulgaria"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Bulgaria"]},{"k":"p","s":["Telephone: 112 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find?country=Bulgaria&serviceType=lawyers"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find?country=Bulgaria&serviceType=funeralDirectors"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find?country=Bulgaria&serviceType=translatorsInterpreters"]," in Bulgaria"]},{"k":"li","s":["dealing with a ",["death in Bulgaria","https://www.gov.uk/guidance/what-to-do-after-a-british-person-dies-in-bulgaria"]]},{"k":"li","s":["being ",["arrested in Bulgaria","https://www.gov.uk/government/publications/bulgaria-prisoner-pack/information-pack-for-british-nationals-detained-or-imprisoned-in-bulgaria"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/bulgaria/british-embassy-sofia"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/bulgaria/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Bulgaria","https://www.gov.uk/government/publications/overseas-business-risk-bulgaria"]," on how to manage political, economic, and business security-related risks."]}],"chars":26362,"change":"Updated information on European Entry-Exit System (EES) (‘Entry requirements’ page)."}};
